package com.bank.loan.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Longest on-time streak achievable after waiving at most k missed days.
public class LoanHistoryAnalyzer {
    private static final Logger log = Logger.getLogger(LoanHistoryAnalyzer.class.getName());

    // history: 1 = paid on time, 0 = missed. k = max waivers allowed.
    public int longestOnTimeStreak(int[] history, int k) {
        if (history == null || history.length == 0) {
            return 0;
        }
        int left = 0;
        int zeros = 0;
        int best = 0;

        for (int right = 0; right < history.length; right++) {
            if (history[right] == 0) {
                zeros++;
            }
            // Too many missed days inside the window: tighten from the left.
            while (zeros > k) {
                if (history[left] == 0) {
                    zeros--;
                }
                final int ls = left;
                log.fine(() -> "Waiver budget exceeded; advancing left from " + ls);
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        final int result = best;
        log.info(() -> "Longest on-time streak with k=" + k + " waivers over history "
                + Arrays.toString(history) + " = " + result);
        return result;
    }
}
