package com.bank.loan;

import com.bank.loan.model.Account;
import com.bank.loan.service.LoanHistoryAnalyzer;

import java.math.BigDecimal;
import java.util.Date;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class OnesAfterReplacementDemo {
    private static final Logger log = Logger.getLogger(OnesAfterReplacementDemo.class.getName());

    public static void main(String[] args) {
        setupLogging();
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        LoanHistoryAnalyzer analyzer = new LoanHistoryAnalyzer();
        int k = 2;

        int[] rajeshHistory = {1, 1, 0, 1, 0, 0, 1, 1, 1};
        log.info(() -> rajesh.getHolderName() + " (" + rajesh.getAccountId() + ") loan history");
        int r1 = analyzer.longestOnTimeStreak(rajeshHistory, k);
        log.info(() -> rajesh.getHolderName() + " best on-time streak = " + r1);

        int[] priyaHistory = {0, 0, 1, 1, 0, 1, 1, 0};
        log.info(() -> priya.getHolderName() + " (" + priya.getAccountId() + ") loan history");
        int r2 = analyzer.longestOnTimeStreak(priyaHistory, k);
        log.info(() -> priya.getHolderName() + " best on-time streak = " + r2);
    }

    private static void setupLogging() {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.FINE);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.FINE);
    }

    static class BankLogFormatter extends Formatter {
        @Override
        public String format(LogRecord r) {
            return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                    new Date(r.getMillis()), r.getLevel(), r.getMessage());
        }
    }
}
